functions.body:
block([row, A, pivots],
    row:1,
    pivots: sort(pivots_cols),
    A:zeromatrix(m,n),
    for i thru length(pivots) do(
        piv: pivots[i],
        A[row][piv]:1,
        for j:piv+1 thru n do (
            A[row][j]:rand_with_prohib(min_val,max_val,[])
            ),
        row:row+1
        ),
     for i thru length(pivots) do(
        piv: pivots[i],
        for j:1 thru i-1 do (
            A[j][piv]:0
            )
        ),
    A)

block([L,h,res,prev,zr,l],L:args(M),h:length(L),res:[0,1,1,1,1],prev:0,zr:0,
 for i:1 thru h do (l:leadc(L[i]),if res[1]=0 then (if l=0 then (if zr=0 then zr:i) else if zr>0 then res:[1,zr,i,1,1] else if l<=prev then res:[2,i-1,i,prev,l] else prev:l)),
 if res[1]=0 and zr=1 then res:[5,1,1,1,1],res)
